double NormalizeYawDegrees(const double YawDegrees)
{
    double Result = FMath::Fmod(YawDegrees, 360.0);
    if (Result < -180.0) { Result += 360.0; }
    else if (Result >= 180.0) { Result -= 360.0; }
    return Result;
}

